<?php require_once __DIR__.'/../_bootstrap.php';admin();$d=body();required($d,['user_id','days_remaining']);$days=(int)$d['days_remaining'];if($days<0||$days>3650)fail('Days must be between 0 and 3650.');$check=db()->prepare('SELECT id FROM users WHERE id=? AND role=\'seller\'');$check->execute([$d['user_id']]);if(!$check->fetch())fail('Seller not found.',404);$q=db()->prepare("UPDATE users SET status=?,subscription_status=?,subscription_start_at=NOW(),subscription_end_at=NULL,trial_ends_at=DATE_ADD(NOW(),INTERVAL ? DAY) WHERE id=?");$q->execute([$days>0?'active':'suspended',$days>0?'trial':'expired',$days,$d['user_id']]);out(['success'=>true,'message'=>'Remaining trial days updated successfully.']);
